<template>
  <div class="chat-room-modal" v-if="visible" @click.self="closeModal">
    <div class="chat-room-container">
      <div class="chat-room-header">
        <div class="header-title">
          <span class="header-icon">💬</span>
          <span>学习交流室</span>
        </div>
        <button class="close-btn" @click="closeModal">×</button>
      </div>
      
      <div class="chat-room-body">
        <div class="online-users-panel">
          <div class="panel-header">
            <span>👥 在线同学</span>
            <span class="online-count">{{ onlineUsers.length }}人在线</span>
          </div>
          <div class="users-list">
            <div 
              v-for="user in onlineUsers" 
              :key="user.userId"
              class="user-item"
              :class="{ 'active': currentChatUser && currentChatUser.userId === user.userId, 'is-me': user.userId === myUserId }"
              @click="selectUser(user)"
            >
              <div class="user-avatar">{{ (user.userName || '用户').charAt(0) }}</div>
              <div class="user-info">
                <div class="user-name">{{ user.userName || '用户' }}{{ user.userId === myUserId ? ' (我)' : '' }}</div>
              </div>
              <div class="user-status"></div>
            </div>
            <div v-if="onlineUsers.length === 0" class="no-users">
              暂无在线用户
            </div>
          </div>
        </div>
        
        <div class="chat-panel">
          <div class="chat-type-tabs">
            <div 
              class="tab-item" 
              :class="{ 'active': chatType === 'group' }"
              @click="switchToGroup"
            >
              🌐 群聊
            </div>
            <div 
              v-if="currentChatUser"
              class="tab-item" 
              :class="{ 'active': chatType === 'private' }"
              @click="switchToPrivate"
            >
              💬 与 {{ currentChatUser.userName }} 私聊
            </div>
          </div>
          
          <div class="messages-container" ref="messagesContainer">
            <div 
              v-for="(msg, index) in currentMessages" 
              :key="index"
              class="message-item"
              :class="{ 'mine': msg.senderId === myUserId }"
            >
              <div class="message-avatar">{{ (msg.senderName || '用户').charAt(0) }}</div>
              <div class="message-content">
                <div class="message-header">
                  <span class="sender-name">{{ msg.senderName || '用户' }}</span>
                  <span class="message-time">{{ formatTime(msg.createTime) }}</span>
                </div>
                <div class="message-text">{{ msg.content }}</div>
              </div>
            </div>
            <div v-if="currentMessages.length === 0" class="no-messages">
              暂无消息，开始聊天吧~
            </div>
          </div>
          
          <div class="input-area">
            <input 
              type="text" 
              v-model="inputMessage" 
              placeholder="输入消息..." 
              @keyup.enter="sendMessage"
              class="message-input"
            >
            <button class="send-btn" @click="sendMessage" :disabled="!inputMessage.trim()">
              发送
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { get } from '@/utils/request'

export default {
  name: 'ChatRoomModal',
  props: {
    visible: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      myUserId: '',
      myUserName: '',
      onlineUsers: [],
      groupMessages: [],
      privateMessages: {},
      currentChatUser: null,
      chatType: 'group',
      inputMessage: '',
      websocket: null,
      reconnectTimer: null
    }
  },
  computed: {
    currentMessages() {
      if (this.chatType === 'group') {
        return this.groupMessages
      } else if (this.currentChatUser) {
        return this.privateMessages[this.currentChatUser.userId] || []
      }
      return []
    }
  },
  watch: {
    visible(val) {
      if (val) {
        this.initChat()
      } else {
        this.closeWebSocket()
      }
    }
  },
  methods: {
    initChat() {
      this.getCurrentUserInfo()
      this.connectWebSocket()
      this.loadGroupMessages()
    },
    getCurrentUserInfo() {
      const userInfoStr = window.localStorage.getItem('user_info')
      if (userInfoStr) {
        const userInfo = JSON.parse(userInfoStr)
        this.myUserId = String(userInfo.id || '')
        this.myUserName = userInfo.userName || userInfo.name || '用户'
      }
    },
    connectWebSocket() {
      if (this.websocket) {
        this.websocket.close()
      }
      
      const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
      const host = window.location.host
      const wsUrl = `${protocol}//${host}/chat/${this.myUserId}`
      
      try {
        this.websocket = new WebSocket(wsUrl)
        
        this.websocket.onopen = () => {
          console.log('WebSocket连接成功')
          this.websocket.send(JSON.stringify({
            type: 'init',
            userId: this.myUserId,
            userName: this.myUserName
          }))
        }
        
        this.websocket.onmessage = (event) => {
          this.handleWebSocketMessage(event.data)
        }
        
        this.websocket.onclose = () => {
          console.log('WebSocket连接关闭')
          this.scheduleReconnect()
        }
        
        this.websocket.onerror = (error) => {
          console.error('WebSocket错误:', error)
        }
      } catch (error) {
        console.error('WebSocket连接失败:', error)
        this.scheduleReconnect()
      }
    },
    scheduleReconnect() {
      if (this.reconnectTimer) {
        clearTimeout(this.reconnectTimer)
      }
      this.reconnectTimer = setTimeout(() => {
        if (this.visible) {
          this.connectWebSocket()
        }
      }, 3000)
    },
    closeWebSocket() {
      if (this.reconnectTimer) {
        clearTimeout(this.reconnectTimer)
      }
      if (this.websocket) {
        this.websocket.close()
        this.websocket = null
      }
    },
    handleWebSocketMessage(data) {
      try {
        const message = JSON.parse(data)
        
        switch (message.type) {
          case 'onlineUsers':
            this.onlineUsers = message.users || []
            break
          case 'group':
            this.groupMessages.push({
              senderId: message.senderId,
              senderName: message.senderName,
              content: message.content,
              createTime: message.createTime
            })
            this.scrollToBottom()
            break
          case 'private':
            const senderId = message.senderId
            if (!this.privateMessages[senderId]) {
              this.privateMessages[senderId] = []
            }
            this.privateMessages[senderId].push({
              senderId: message.senderId,
              senderName: message.senderName,
              content: message.content,
              createTime: message.createTime
            })
            if (this.chatType === 'private' && this.currentChatUser && this.currentChatUser.userId === senderId) {
              this.scrollToBottom()
            }
            break
        }
      } catch (error) {
        console.error('解析WebSocket消息失败:', error)
      }
    },
    async loadGroupMessages() {
      try {
        const res = await get('/chat/groupMessages')
        if (res.success && Array.isArray(res.data)) {
          this.groupMessages = res.data.reverse()
          this.scrollToBottom()
        }
      } catch (error) {
        console.error('加载群聊消息失败:', error)
      }
    },
    async loadPrivateMessages(userId) {
      try {
        const res = await get('/chat/privateMessages', { userId2: userId })
        if (res.success && Array.isArray(res.data)) {
          this.privateMessages[userId] = res.data
          this.scrollToBottom()
        }
      } catch (error) {
        console.error('加载私聊消息失败:', error)
      }
    },
    selectUser(user) {
      if (user.userId === this.myUserId) return
      
      this.currentChatUser = user
      this.chatType = 'private'
      
      if (!this.privateMessages[user.userId]) {
        this.loadPrivateMessages(user.userId)
      }
    },
    switchToGroup() {
      this.chatType = 'group'
      this.currentChatUser = null
      this.scrollToBottom()
    },
    switchToPrivate() {
      this.chatType = 'private'
      this.scrollToBottom()
    },
    sendMessage() {
      if (!this.inputMessage.trim() || !this.websocket) return
      
      const message = {
        type: this.chatType,
        content: this.inputMessage.trim()
      }
      
      if (this.chatType === 'private' && this.currentChatUser) {
        message.receiverId = this.currentChatUser.userId
      }
      
      this.websocket.send(JSON.stringify(message))
      this.inputMessage = ''
    },
    scrollToBottom() {
      this.$nextTick(() => {
        const container = this.$refs.messagesContainer
        if (container) {
          container.scrollTop = container.scrollHeight
        }
      })
    },
    formatTime(timestamp) {
      if (!timestamp) return ''
      const date = new Date(timestamp)
      const now = new Date()
      const isToday = date.toDateString() === now.toDateString()
      
      if (isToday) {
        return date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })
      } else {
        return date.toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
      }
    },
    closeModal() {
      this.$emit('update:visible', false)
      this.$emit('close')
    }
  },
  beforeUnmount() {
    this.closeWebSocket()
  }
}
</script>

